const getRows=<T,>(data:any):T[]=>Array.isArray(data)?data:Array.isArray(data?.results)?data.results:[];
async function api<T=any>(path:string, init?:RequestInit):Promise<T>{
 const token=localStorage.getItem('imena-token');
 const headers=new Headers(init?.headers);
 if(!(init?.body instanceof FormData)&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');
 if(token)headers.set('Authorization',`Token ${token}`);
 let response:Response|undefined;
 for(let attempt=0;attempt<2;attempt++){
  try{
   const controller=new AbortController();
   const timeout=window.setTimeout(()=>controller.abort(),15000);
   try{
    response=await fetch(apiUrl('/api'+path),{...init,headers,signal:controller.signal});
    break;
   }catch{
    if(attempt===0)await new Promise(resolve=>window.setTimeout(resolve,1200));
   }finally{clearTimeout(timeout)}
  }catch{throw new Error('Live listings could not be loaded. Check your connection and retry.')}
 }
 if(!response)throw new Error('The live API is temporarily unavailable. Please try again in a moment.');
 const text=await response.text();
 let data:any;
 try{data=text?JSON.parse(text):{}}
 catch{if(!response.ok){if(response.status===404)throw new Error('This API resource was not found. Please refresh the page and try again.');throw new Error(`The API returned an unreadable response (HTTP ${response.status}). Please try again or contact support.`)}throw new Error('The server returned a non-JSON response.')}
 if(!response.ok)throw new Error(data.detail||Object.values(data).flat().join(' ')||`Request failed (${response.status})`);
 return data;
}

