 useEffect(()=>{if(!showBooking||!bookForm.date||!bookForm.time||!bookForm.end_date||!bookForm.end_time){setAvailability(null);return}const service=showBooking;const starts=new Date(`${bookForm.date}T${bookForm.time}`),ends=new Date(`${bookForm.end_date}T${bookForm.end_time}`);if(Number.isNaN(starts.getTime())||Number.isNaN(ends.getTime())||ends<=starts){setAvailability({available:false,remaining:0});return}let alive=true;const params=new URLSearchParams({starts_at:starts.toISOString(),ends_at:ends.toISOString(),party_size:String(bookForm.party_size)});api<{available:boolean;remaining:number}>(`/services/${service.id}/availability/?${params}`).then(x=>{if(alive)setAvailability(x)}).catch(()=>{if(alive)setAvailability({available:false,remaining:0})});return()=>{alive=false}},[showBooking,bookForm.date,bookForm.time,bookForm.end_date,bookForm.end_time,bookForm.party_size]);
 const visibleProducts=useMemo(()=>products.filter(p=>(!category||p.category_name===category)&&(!district||p.district?.toLowerCase().includes(district.toLowerCase()))),[products,category,district]);
