 const cartRows=products.filter(p=>cart[p.id]);const subtotal=cartRows.reduce((sum,p)=>sum+Number(p.price)*(cart[p.id]||0),0);const vatTotal=cartRows.reduce((sum,p)=>{if(p.business_tax_registration!=='vat_registered'||p.vat_category!=='standard')return sum;const amount=Number(p.price)*(cart[p.id]||0);return sum+(p.prices_include_vat?amount*18/118:amount*.18)},0);const total=subtotal+cartRows.reduce((sum,p)=>p.business_tax_registration==='vat_registered'&&p.vat_category==='standard'&&!p.prices_include_vat?sum+Number(p.price)*(cart[p.id]||0)*.18:sum,0);
 const flash=(message:string)=>{setNotice(message);window.setTimeout(()=>setNotice(''),4000)};
 const loadSellerReport=async(business=reportBusiness,days=reportDays)=>{setReportLoading(true);try{const params=new URLSearchParams({days:String(days)});if(business)params.set('business',business);const result=await api<SellerReport>(`/seller/reports/?${params}`);setSellerReport(result);if(result.selected_business)setReportBusiness(result.selected_business.id)}catch(e){setSellerReport(null);flash((e as Error).message)}finally{setReportLoading(false)}};
