 const submitBooking=async(e:React.FormEvent)=>{e.preventDefault();if(!showBooking)return;setWorking(true);try{const starts=new Date(`${bookForm.date}T${bookForm.time}`).toISOString(),ends=new Date(`${bookForm.end_date}T${bookForm.end_time}`).toISOString();const result=await api<Booking>('/bookings/',{method:'POST',body:JSON.stringify({service:showBooking.id,starts_at:starts,ends_at:ends,party_size:Number(bookForm.party_size),guest_name:bookForm.name,guest_phone:bookForm.phone,notes:bookForm.notes})});setBooking(result);setShowBooking(null);flash(`Booking ${result.reference} requested · quoted ${money(result.total||0)} including ${money(result.vat_amount||0)} VAT where applicable. Payment is not collected here.`)}catch(e){flash((e as Error).message)}finally{setWorking(false)}};
